package com.codepathacademy.curriculum;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class ContentService {
 private final TopicRepository topics; private final ClassTopicRepository classTopics; private final LessonContentRepository lessons; private final ObjectMapper json;
 public ContentService(TopicRepository topics,ClassTopicRepository classTopics,LessonContentRepository lessons,ObjectMapper json){this.topics=topics;this.classTopics=classTopics;this.lessons=lessons;this.json=json;}
 public List<TopicView> classTopics(UUID classId,String locale){return classTopics.findByCurriculumClassIdOrderBySortOrder(classId).stream().map(link->topic(link.getTopic(),locale)).toList();}
 public TopicView topic(UUID id,String locale){return topic(topics.findById(id).orElseThrow(()->new NoSuchElementException("Topic not found")),locale);}
 public List<TopicView> prerequisites(UUID id,String locale){topics.findById(id).orElseThrow(()->new NoSuchElementException("Topic not found"));return List.of();}
 public LessonView lesson(UUID id,String locale){var l=lessons.findById(id).orElseThrow(()->new NoSuchElementException("Lesson not found"));return view(l,locale);}
 public LessonView classLesson(UUID classId,String locale){return view(lessons.findByCurriculumClassId(classId).orElseThrow(()->new NoSuchElementException("Lesson not found")),locale);}
 private TopicView topic(Topic topic,String locale){boolean wantsMl="ml-IN".equals(locale)||"both".equals(locale);var children=topics.findByParentIdOrderBySortOrder(topic.getId()).stream().map(t->topic(t,locale)).toList();return new TopicView(topic.getId(),topic.getCode(),new Localized(topic.getTitleEn(),topic.getTitleMl(),wantsMl&&topic.getTitleMl()==null),new Localized(topic.getDescriptionEn(),topic.getDescriptionMl(),wantsMl&&topic.getDescriptionMl()==null),topic.getParent()==null?null:topic.getParent().getId(),children,List.of());}
 private LessonView view(LessonContent l,String locale){boolean requestedMl="ml-IN".equals(locale)||"both".equals(locale);boolean available=l.getMalayalamBody()!=null;return new LessonView(l.getId(),l.getCurriculumClass().getId(),l.getCurriculumClass().getCode(),l.getEditorialStatus(),locale,available?locale:"en-IN",requestedMl&&!available,l.getVersion(),blocks(l.getContentBlocks()));}
 private List<JsonNode> blocks(String content){try{return json.readTree(content).isArray()?java.util.stream.StreamSupport.stream(json.readTree(content).spliterator(),false).toList():List.of();}catch(Exception ex){throw new IllegalStateException("Stored lesson content is invalid",ex);}}
 public record Localized(String english,String malayalam,boolean fallback){} public record TopicView(UUID id,String code,Localized title,Localized description,UUID parentId,List<TopicView> subtopics,List<TopicView> prerequisites){} public record LessonView(UUID id,UUID classId,String classCode,String publicationState,String requestedLocale,String actualContentLocale,boolean fallback,long revision,List<JsonNode> blocks){}
}
